@override
Widget build(BuildContext context) {
  final palette = Theme.of(context).extension<AppPalette>()!;
  final typography = Theme.of(context).extension<AppTypography>()!;

  // read (not watch): the dot animates off [spectrumListenable] below, so this
  // widget must NOT rebuild on every controller notify.
  final player = context.read<PlaybackController>();

  const titleTop = 12.0;
  const titleToDotGap = 8.0;
  const headingHeightFactor = 1.18; // matches heroHeadingStyle().height

  final titleHeightEstimateForBothLines =
      (2 * typography.heroSize /*H1*/ + 2 * typography.heroSize * heroSongSizeFactor /*H2*/)
          * config.textScale * headingHeightFactor + 8.0 /*artist→song gap*/;

  return LayoutBuilder(
    builder: (context, constraints) {
      final maxW = constraints.maxWidth;
      final maxH = constraints.maxHeight;

      // Reserve space for the song-info overlay so the centered dot never
      // intersects the (potentially very tall) artist+song text.
      final dotRegionTop = config.showSongInfo
          ? titleTop + titleHeightEstimateForBothLines + titleToDotGap
          : 0.0;
      final dotRegionHeight = (maxH - dotRegionTop).clamp(0.0, double.infinity);

      final maxAllowedBySize = min(maxW, maxH) / 2;
      final maxAllowedByRegion = dotRegionHeight / 2;
      final maxAllowed = min(maxAllowedBySize, maxAllowedByRegion);

      final dotCenterY = dotRegionTop + dotRegionHeight / 2;

      return BaseHeroContainer(
        child: Stack(
          clipBehavior: Clip.none,
          children: [
            // Pulsing dot — centered within the remaining (post-title) region.
            RepaintBoundary(
              child: AnimatedBuilder(
                animation: player.spectrumListenable,
                builder: (context, _) {
                  final r = _radiusFor(player.spectrumData, maxAllowed);
                  final diameter = r * 2;
                  final left = (maxW - diameter) / 2;
                  final top = dotCenterY - r;
                  return Positioned(
                    left: left,
                    top: top,
                    child: Container(
                      width: diameter,
                      height: diameter,
                      decoration: BoxDecoration(
                        color: palette.fgPrimary
                            .withValues(alpha: config.dotOpacity),
                        shape: BoxShape.circle,
                      ),
                    ),
                  );
                },
              ),
            ),

            // Optional song-info overlay pinned to the top of the hero band
            // (B-020), above the dot.
            if (config.showSongInfo)
              Positioned(
                left: 0,
                right: 0,
                top: titleTop,
                child: Opacity(
                  opacity: config.textOpacity.clamp(0.0, 1.0),
                  child: HeroTitleBlock(textScale: config.textScale),
                ),
              ),
          ],
        ),
      );
    },
  );
}

